//! Frozen surveyed scalar endpoint trace references.
//!
//! Each row holds one interior state, one end, and one policy. Trace values use the
//! outward frame: velocity and discharge are positive when water leaves the reach.
//! Interior discharge and `Policy::Discharge` are global, positive toward +x.

// Generated by `transcribe.py` in `resource/evidence/surveyed-endpoints/` from its
// frozen `reference.json`. Regenerate instead of editing.

use super::surveyed_profiles::*;
use hydr::channel::ChannelBoundary;

/// One 150-digit reference: its nearest binary64 and the directed bounds that enclose it.
#[derive(Clone, Copy, Debug)]
pub struct Value {
    pub nearest: f64,
    pub floor_bits: u64,
    pub ceil_bits: u64,
}

impl Value {
    pub fn floor(self) -> f64 {
        f64::from_bits(self.floor_bits)
    }

    pub fn ceil(self) -> f64 {
        f64::from_bits(self.ceil_bits)
    }
}

pub const fn v(nearest: f64, floor_bits: u64, ceil_bits: u64) -> Value {
    Value {
        nearest,
        floor_bits,
        ceil_bits,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum End {
    Left,
    Right,
}

/// A scalar endpoint policy with its exact binary64 operands.
#[derive(Clone, Copy, Debug)]
pub enum Policy {
    Stage {
        elevation_m: f64,
    },
    /// Global discharge, positive toward +x.
    Discharge {
        discharge_m3_per_s: f64,
    },
    Reservoir {
        elevation_m: f64,
        entrance_loss_coefficient: f64,
    },
}

impl Policy {
    pub fn boundary(self) -> ChannelBoundary {
        match self {
            Self::Stage { elevation_m } => ChannelBoundary::Stage { elevation_m },
            Self::Discharge { discharge_m3_per_s } => {
                ChannelBoundary::Discharge { discharge_m3_per_s }
            }
            Self::Reservoir {
                elevation_m,
                entrance_loss_coefficient,
            } => ChannelBoundary::QuiescentReservoir {
                elevation_m,
                entrance_loss_coefficient,
            },
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Trace {
    /// Frozen fixture name for identity rows, empty for multi-band rows.
    pub fixture: &'static str,
    pub profile: Profile,
    pub gravity: f64,
    pub interior_area_m2: f64,
    pub interior_discharge_m3_per_s: f64,
    pub end: End,
    pub policy: Policy,
    /// Outward discharge is positive.
    pub leaving: bool,
    /// Zero-based band that holds the trace depth.
    pub band: usize,
    pub depth: Value,
    pub area: Value,
    pub outward_velocity: Value,
    pub outward_discharge: Value,
    /// `A u^2 + g I(A)` of the trace.
    pub momentum_flux: Value,
    /// `sqrt(g A / T)` of the trace.
    pub sound: Value,
    /// Reservoir rows: `d + (1 + k) max(-u, 0)^2 / (2 g)`.
    pub head: Option<Value>,
    /// Reservoir rows: `max(q, 0) u^2 / 2 + k max(-q, 0) u^2 / 2`.
    pub dissipation: Option<Value>,
    /// Discharge rows: the leaving-flow sonic depth that bounds the root bracket.
    pub sonic_depth: Option<Value>,
}

