#[test]
fn surveyed_endpoint_trace_references_load() {
    let rows = [IDENTITY_RESERVOIR, IDENTITY_LITERAL, MULTIBAND];
    assert_eq!(rows.map(<[Trace]>::len), [12, 16, 280]);
    for row in rows.into_iter().flatten() {
        let _ = row.policy.boundary();
        assert!(f64::from_bits(row.profile.cap) > 0.0);
        for value in [
            row.depth,
            row.area,
            row.outward_velocity,
            row.outward_discharge,
            row.momentum_flux,
            row.sound,
        ]
        .into_iter()
        .chain(row.head)
        .chain(row.dissipation)
        .chain(row.sonic_depth)
        {
            assert!(value.floor() <= value.nearest && value.nearest <= value.ceil());
        }
    }
}
